import os,sys,json,hashlib,subprocess,time
from pathlib import Path
ROOT=Path('/Users/yuxianqi/Project/qlib');os.chdir(ROOT);sys.path.insert(0,str(ROOT))
T=Path('/private/tmp/qlib-overlay-20261125-wxqZ2a');PY='/opt/anaconda3/envs/qlib/bin/python'
S=ROOT/'backtest/experiments/strategies/topk-dropout/market-exposure-20261125'
