def dump(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def ref(p):return str(Path(p).relative_to(ROOT)) if Path(p).is_relative_to(ROOT) else str(Path(p).resolve())
def fp(p):return {'path':ref(p),'sha256':sha(p),'size':Path(p).stat().st_size}
def cli(args):
 r=subprocess.run([PY,str(ROOT/'backtest/scripts/maintenance/experiment_harness.py')]+args,cwd=ROOT,capture_output=True,text=True)
 if r.returncode:raise RuntimeError(r.stdout+r.stderr)
 return json.loads(r.stdout)
def statepath():return S/'docs/harness-state.json'
def event(data):
 st=cli(['status','--state',str(statepath())]);p=T/'event.json';dump(p,data);st=cli(['event','--state',str(statepath()),'--event',str(p),'--expected-revision',str(st['revision'])]);print('EVENT',data['type'],st['revision'],flush=True);return st
def check(kind=None):return cli(['check','--state',str(statepath())])
def ledger(job,kind,status,details):
 p=S/'docs/internal-jobs.jsonl'
 with p.open('a') as f:f.write(json.dumps({'job':job,'kind':kind,'status':status,'time':time.time(),**details},ensure_ascii=False,allow_nan=False)+'\n')
